 if(b.boss){const boss=b.boss;const g=this.bossModel?.userData.id===boss.id?this.bossModel:this.createBoss(boss);g.visible=true;g.position.set(boss.x,0,boss.z);g.userData.body.rotation.z=Math.sin(boss.age*1.8)*.055;g.userData.body.position.y=Math.sin(boss.age*(boss.index===2?3:2))*(boss.index===2?.8:.12);g.userData.head.rotation.x=boss.attack<1?-.2:Math.sin(boss.age)*.04;g.userData.head.rotation.y=Math.sin(boss.age)*.2;g.userData.jaw.rotation.x=boss.open?Math.sin(boss.age*3)*.18+.2:0;g.userData.limbs.forEach((limb,i)=>limb.rotation.x=Math.sin(boss.age*2+i*Math.PI)*.3+(boss.attack<1?-.7:0));g.userData.wings?.forEach((w,i)=>w.rotation.z=Math.sin(boss.age*3)*(i?1:-1)*.3);g.userData.weak.position.x=boss.weakX-boss.x;g.userData.ring.position.x=boss.weakX-boss.x;g.userData.ring.rotation.z=time;g.userData.weak.scale.setScalar(boss.open?.55:.34);g.userData.ring.visible=boss.open;}else if(this.bossModel)this.bossModel.visible=false;
 for(const p of b.shots){const a=Math.atan2(p.tx-p.x,p.tz-p.z);this.instance('arrow','box','#ffe6af',p.x,1.05+Math.sin(Math.min(1,1.8-p.life)*3)*.7,p.z,.045,.045,1.1,0,a);this.instance('arrowhead','cone','#e9f5ed',p.x,1.05,p.z-.5,.1,.24,.1,-Math.PI/2,0,0);}
 for(const d of b.drops)this.instance('gold'+d.type,'rock',d.type==='troops'?'#8df0bc':d.type==='weapon'?'#addbfa':'#ffdc76',d.x,.65+Math.sin(time*6+d.id)*.15,d.z,.22,.3,.12,0,time*3);
 for(const h of b.hazards){const color=h.triggered?'#ffb878':'#d15857';const opacity=h.delay<.65?.8:.35;this.instance('hazard'+color,'box',color,h.x,.06,2,h.width,.035,7);for(let i=0;i<5;i++)this.instance('warn','box','#ffe4a1',h.x+(i-2)*h.width/6,.09,5,.08,.035,.55,0,0,.5);if(h.triggered){for(let i=0;i<6;i++)this.instance('burst','cone',h.kind==='ice'?'#c9f3ff':'#ffbc6e',h.x+(i-2.5)*.5,(.6-h.life)*4,1.5+i%2,.25,2*h.life,.25);}else if(h.kind==='boulder'||h.kind==='arrow')this.instance('enemyshot','rock','#e87558',h.x,3+h.delay*4,2-h.delay*12,h.kind==='boulder'?.6:.1,h.kind==='boulder'?.6:.1,h.kind==='boulder'?.6:.7);}
